window.ScripturaLexicons.BDAG_PART_0255 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-01\" data-source=\"BDAG\" data-search=\"ὅμοιος, οία, οιον adjetivo semelhante; da mesma natureza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅμοιος, οία, οιον</td><td>adjetivo</td><td>semelhante; da mesma natureza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-02\" data-source=\"BDAG\" data-search=\"ὁμοιότης, ητος, ἡ substantivo feminino semelhança; similitude BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοιότης, ητος, ἡ</td><td>substantivo feminino</td><td>semelhança; similitude</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-03\" data-source=\"BDAG\" data-search=\"ὁμοιοτρόπως advérbio da mesma maneira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοιοτρόπως</td><td>advérbio</td><td>da mesma maneira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-04\" data-source=\"BDAG\" data-search=\"ὁμοιόω verbo tornar semelhante; comparar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοιόω</td><td>verbo</td><td>tornar semelhante; comparar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-05\" data-source=\"BDAG\" data-search=\"ὁμοίωμα, ατος, τό substantivo neutro semelhança; imagem; forma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοίωμα, ατος, τό</td><td>substantivo neutro</td><td>semelhança; imagem; forma</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-06\" data-source=\"BDAG\" data-search=\"ὁμοίως advérbio igualmente; do mesmo modo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοίως</td><td>advérbio</td><td>igualmente; do mesmo modo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-07\" data-source=\"BDAG\" data-search=\"ὁμοίωσις, εως, ἡ substantivo feminino semelhança; similitude BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοίωσις, εως, ἡ</td><td>substantivo feminino</td><td>semelhança; similitude</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-08\" data-source=\"BDAG\" data-search=\"ὁμολογέω verbo prometer; concordar; confessar; louvar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμολογέω</td><td>verbo</td><td>prometer; concordar; confessar; louvar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-09\" data-source=\"BDAG\" data-search=\"ὁμολόγησις, ήσεως, ἡ substantivo feminino profissão; confissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμολόγησις, ήσεως, ἡ</td><td>substantivo feminino</td><td>profissão; confissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-10\" data-source=\"BDAG\" data-search=\"ὁμολογία, ας, ἡ substantivo feminino profissão de fé; confissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμολογία, ας, ἡ</td><td>substantivo feminino</td><td>profissão de fé; confissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-11\" data-source=\"BDAG\" data-search=\"ὁμολογουμένως advérbio incontestavelmente; certamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμολογουμένως</td><td>advérbio</td><td>incontestavelmente; certamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-12\" data-source=\"BDAG\" data-search=\"ὁμονοέω verbo concordar; viver em harmonia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμονοέω</td><td>verbo</td><td>concordar; viver em harmonia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-13\" data-source=\"BDAG\" data-search=\"ὁμόνοια, ας, ἡ substantivo feminino concórdia; unanimidade; harmonia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμόνοια, ας, ἡ</td><td>substantivo feminino</td><td>concórdia; unanimidade; harmonia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-14\" data-source=\"BDAG\" data-search=\"ὁμόσε advérbio para um mesmo lugar; juntos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμόσε</td><td>advérbio</td><td>para um mesmo lugar; juntos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-15\" data-source=\"BDAG\" data-search=\"ὁμότεχνος, ον adjetivo da mesma profissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμότεχνος, ον</td><td>adjetivo</td><td>da mesma profissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-16\" data-source=\"BDAG\" data-search=\"ὁμοῦ advérbio juntos; ao mesmo tempo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοῦ</td><td>advérbio</td><td>juntos; ao mesmo tempo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-17\" data-source=\"BDAG\" data-search=\"ὁμόφρων, ον adjetivo unido em espírito; harmonioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμόφρων, ον</td><td>adjetivo</td><td>unido em espírito; harmonioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-18\" data-source=\"BDAG\" data-search=\"ὁμόφυλος, ον adjetivo da mesma tribo; compatriota BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμόφυλος, ον</td><td>adjetivo</td><td>da mesma tribo; compatriota</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-19\" data-source=\"BDAG\" data-search=\"ὁμοφωνία, ας, ἡ substantivo feminino harmonia; concordância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁμοφωνία, ας, ἡ</td><td>substantivo feminino</td><td>harmonia; concordância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0255-20\" data-source=\"BDAG\" data-search=\"ὄμφαξ, ακος substantivo feminino/masculino uva verde; uva imatura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄμφαξ, ακος</td><td>substantivo feminino/masculino</td><td>uva verde; uva imatura</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0255-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅμοιος, οία, οιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅμοιος</span>, <span class=\"greek\">οία</span>, <span class=\"greek\">οιον</span> (<span class=\"greek\">ὁμός</span>, «comum»; Hom. e posteriores.—Sobre a acentuação, ver B-D-F § 13; Mlt-H. 58. Sobre <span class=\"greek\">ἡ</span> <span class=\"greek\">ὅμοιος</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:3b</a>, ver a abaixo e B-D-F § 59, 2; Mlt-H. 157), da mesma natureza, semelhante, parecido. ⓐ Com dativo da pessoa ou coisa comparada (regra geral desde Hom. e outros): <span class=\"greek\">ὅμ</span>. <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἐστιν</span>, ele se parece com aquele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:9</a>.—<span class=\"greek\">χρυσῷ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀγρύρῳ</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ὅμ</span>., a divindade é semelhante ao ouro ou à prata, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:29</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅμ</span>. <span class=\"greek\">τούτοις</span>, coisas semelhantes a estas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:21</a>; cf. Hm 8:5, 10; 12, 3, 1; (com <span class=\"greek\">παραπλήσιος</span>) 6, 2, 5. <span class=\"greek\">ὅμ</span>. <span class=\"greek\">ὁράσει</span> <span class=\"greek\">λίθῳ</span> <span class=\"greek\">ἰάσπιδι</span>, semelhante em aparência ao jaspe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:3a</a>; cf. 3b (aqui <span class=\"greek\">ὁμ</span>. é adjetivo de duas terminações, como Aesop, Fab. 63a H.=59a, 4 Ch. <span class=\"greek\">στήλην</span> <span class=\"greek\">ὅμοιον</span>). <span class=\"greek\">ὅμ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰδέᾳ</span>, semelhante na aparência, Hs 9, 3, 1.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:15</a>; 2:18; 4:6f; 9:7, 19; 11:1; 13:2; 21:11, 18; 1 Cl 35:9 (Ps 49:21); 7:10a; Dg 2:2f; Hs 9, 19, 2; 9, 21, 2. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">ὅμοια</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λοιποῖς</span>, ser feito por mãos humanas em utensílios semelhantes aos demais, Dg 2:4. <span class=\"greek\">ἄλλος</span> <span class=\"greek\">ὅμ</span>. <span class=\"greek\">ἐμοί</span>, algum outro semelhante a mim, Pol 3:2. <span class=\"greek\">ὅμ</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">φαρμάκοις</span>, semelhante aos envenenadores ou mágicos, Hv 3, 9, 7 (cf. lista de vícios Physiogn. I 327, 15). <span class=\"greek\">ἡ</span> <span class=\"greek\">καταστροφὴ</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">καταιγίδι</span>, a destruição é como uma tempestade de vento, 1 Cl 57:4 (cf. Pr 1:27). <span class=\"greek\">ὅμοιοι</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἐσόμεθα</span>, seremos semelhantes a (Deus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:2</a> (cf. Herm. Wr. 11, 5 <span class=\"greek\">ὅμ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; Orig., C. Cels. 4, 30, 10). <span class=\"greek\">ὁ</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅμ</span>. <span class=\"greek\">ποιῶν</span>, aquele que pratica coisas semelhantes a essas, Hs 6, 5, 5. <span class=\"greek\">τὸν</span> <span class=\"greek\">ὅμοιον</span> <span class=\"greek\">τρόπον</span> <span class=\"greek\">τούτοις</span>, da mesma maneira que eles, Jd 7. <span class=\"greek\">ἔσομαι</span> <span class=\"greek\">ὅμοιος</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ψεύστης</span>, eu seria semelhante a vós, um mentiroso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.55\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:55</a> (<span class=\"greek\">ὅ</span>. <span class=\"greek\">αὐτῷ</span>, todo vivente sente afeição «pelo que lhe é semelhante», Sir 13:15; 28:4, sobre quem não tem compaixão de um semelhante). Frequente em parábolas, como <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ἐστίν</span>, é semelhante a (Aristippus em Diog. L. 2, 79, numa parábola: <span class=\"greek\">τὶς</span> <span class=\"greek\">ὅμοιός</span> <span class=\"greek\">ἐστί</span> <span class=\"greek\">τινι</span>; Philosoph. Max 485, 2 M: <span class=\"greek\">ἡ</span> <span class=\"greek\">παιδεία</span> <span class=\"greek\">ὁμοία</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">χρυσῷ</span> <span class=\"greek\">στεφάνῳ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:16</a>; 13:31, 33, 44f, 47, 52; 20:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:47</a>–49; 7:31f; 12:36; 13:18f, 21. <span class=\"greek\">οἵτινές</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">ὅμοιοι</span> <span class=\"greek\">χοίροις</span> (-<span class=\"greek\">ρων</span>, variante de leitura), semelhantes a porcos, 10:3. Em braquilogia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:10</a>. <span class=\"greek\">κέρατα</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ὅμοια</span> <span class=\"greek\">ἀρνίῳ</span>, 13:11.—Em sentido especial, igualmente grande ou importante, tão poderoso quanto, igual a (Gen 2:20; Jos., Ant. 8, 364; cf. lema latino «nec pluribus impar»): <span class=\"greek\">τίς</span> <span class=\"greek\">ὅμ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θηρίῳ</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">πολεμῆσαι</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτοῦ</span>;, quem se iguala à besta, e quem pode combatê-la?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:4</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μεγάλῃ</span>;, 18:18. <span class=\"greek\">δευτέρα</span> (isto é, <span class=\"greek\">ἐντολή</span>) <span class=\"greek\">ὁμοία</span> <span class=\"greek\">αὐτῇ</span> (isto é, <span class=\"greek\">τῇ</span> <span class=\"greek\">πρώτῃ</span>), um segundo mandamento tão importante quanto o primeiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:31</a>, variante de leitura. ⓑ Com genitivo de comparação (Theophr., HP 9, 11, 11; Hero Alex. I p. 60, 16; Aelian, HA 8, 1 <span class=\"greek\">τέτταρας</span> <span class=\"greek\">ὁμοίους</span> <span class=\"greek\">ἐκείνου</span> <span class=\"greek\">κύνας</span>; PIand VI, 97, 9 [III d.C.]; Cat. Cod. Astr. VIII/3 p. 197, 16 <span class=\"greek\">ὅμ</span>. <span class=\"greek\">ὄφεως</span>; Sir 13:16; Tat. 14:2.—Kühner-G. I 413, 10; B-D-F § 182, 4; Rob. 530): <span class=\"greek\">ἔσομαι</span> <span class=\"greek\">ὅμ</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ψεύστης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.55\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:55</a>, variante de leitura (em vez de <span class=\"greek\">ὑμῖν</span>; cf. a acima; Rydbeck, 46–49). <span class=\"greek\">φεῦγε</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">πονηροῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ὁμοίου</span> <span class=\"greek\">αὐτοῦ</span>, evita todo mal e tudo o que se lhe assemelha, D 3:1, variante de leitura; 10:3, ver acima. ⓒ O acusativo de comparação parece não passar de solecismo em <span class=\"greek\">ὅμ</span>. <span class=\"greek\">υἱὸν</span> <span class=\"greek\">ἀνθρώπου</span>, alguém semelhante a um ser humano, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:13</a>; 14:14 (ambos apresentam <span class=\"greek\">υἱῷ</span> como variante de leitura), mas ver RCharles, comentário ad loc.—B-D-F § 182, 4; Rob. 530. ⓓ Uso absoluto: <span class=\"greek\">τράγοι</span> <span class=\"greek\">ὅμ</span>., bodes semelhantes entre si, B 7:6, 10b (Just., D. 40, 4). <span class=\"greek\">ὅμοιοι</span> <span class=\"greek\">ἐγένοντο</span> <span class=\"greek\">λευκοί</span>, todos igualmente se tornaram brancos, Hs 9, 4, 5. (<span class=\"greek\">τὰ</span> <span class=\"greek\">δένδρα</span>) <span class=\"greek\">ξηρά</span> <span class=\"greek\">εἰσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅμοια</span>, (as árvores) são igualmente secas = uma é tão seca quanto a outra, 3:2a; cf. versículo 1b. <span class=\"greek\">ὅμοια</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">πάντα</span>, elas (as árvores) eram todas semelhantes, 3:1a; cf. versículos 2b e 3ab. (Acerca de dissidentes: <span class=\"greek\">ὅμοια</span> <span class=\"greek\">μὲν</span> [isto é, <span class=\"greek\">ἡμῖν</span>, a nós] <span class=\"greek\">λαλοῦντες</span>, <span class=\"greek\">ἀνόμοια</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">φρονοῦντες</span>, Iren. 1, prólogo 2 [Harv. I 4, 5].)—B. 912. Schmidt, Syn. IV 471–87; cf. <span class=\"greek\">ἴσος</span>. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοιότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοιότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὅμοιος</span>; pré-socráticos, Pla., Isocr. e posteriores; Polyb. 6, 53, 5; 13, 7, 2; Plut., Mor. 25b; 780e; Epict. 4, 11, 28; Lucian, Dial. Deor. 6, 5; papiros, LXX; ParJer 9:26f; Philo; Ath. 17, 2; <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἄναλογίαν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λημπτέα</span>, Did., Gen. 57, 18; <span class=\"greek\">ὁμ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> … <span class=\"greek\">εἰκόνα</span>, Hippol., Ref. 4, 27, 2), estado de ser semelhante a algo, semelhança, similitude, concordância: <span class=\"greek\">πάντας</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">εἶναι</span>, que todos vós sejais semelhantes a (Jesus Cristo), IEph 1:3. <span class=\"greek\">ἐκπλήττεσθαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τινος</span>, admirar-se da semelhança com algo, 7:10. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὁμοιότητα</span> (Philo, Fuga 51; Herm. Wr. 464, 29; 518, 13 Sc.; BGU 1028, 15; PSI 107, 2; PGM 1, 211; Gen 1:11, 12), exatamente da mesma maneira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:15</a>. Seguido de genitivo (Dionys. Byz. §29; BGU 1028, 15 [II d.C.]; POxy 1202, 24; PSI 107, 2; Philo, Rer. Div. Her. 232, Spec. Leg. 1, 296; Iren., 1, 15, 5 [Harv. I 154, 7]): <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">Μελχισέδεκ</span>, da mesma maneira que Melquisedeque, 7:15.—DELG s.v. <span class=\"greek\">ὅμοιο</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοιοτρόπως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοιοτρόπως</span>, advérbio de <span class=\"greek\">ὁμοιότροπος</span>, «de maneira semelhante» (Thu. 6, 20, 3; Aristot., Gen. An. 3, 5; Philo, Aet. M. 20 [todos os três com dativo]), da mesma maneira: <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">προειρημένοις</span>, da mesma maneira que os já mencionados, Dg 3:2.—DELG s.v. <span class=\"greek\">ὅμοιο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοιόω</span>, futuro <span class=\"greek\">ὁμοιώσω</span>; 1 aoristo <span class=\"greek\">ὡμοίωσα</span>, LXX; subjuntivo aoristo, 1ª pessoa plural <span class=\"greek\">ὁμοιώσωμεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:30</a>. Passiva: 1 futuro <span class=\"greek\">ὁμοιωθήσομαι</span>; 1 aoristo <span class=\"greek\">ὡμοιώθην</span> (sobre a forma <span class=\"greek\">ὁμοιώθην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:29</a>, variante de leitura, ver W-H., aparato 161); particípio perfeito plural <span class=\"greek\">ὡμοιώμενοι</span> (EpJer 38) (Hom. e posteriores). ① Tornar semelhante, com <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>, tornar alguém semelhante a uma pessoa ou coisa; na passiva, tornar-se semelhante, ser semelhante, com <span class=\"greek\">τινί</span>, a alguém (Ps.-Apollod. 1, 4, 1, 1; Herm. Wr. 1, 26a; PGM 4, 1859; 2500; Sir 13:1; Ps 48:13; Philo, Deus Imm. 48; TestBenj 7:5; <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, Did., Gen. 145, 6; Hippol., Ref. 6, 53, 7): <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀδελφοῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a> (ver Merki no final de <span class=\"greek\">ὁμοίωσις</span>). Sobre divindades (Diod S 1, 86, 3 <span class=\"greek\">ὁμοιωθῆναί</span> <span class=\"greek\">τισιν</span> <span class=\"greek\">ζῴοις</span>): <span class=\"greek\">ὁμοιωθέντες</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">κατέβησαν</span>, desceram assumindo a forma de seres humanos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:11</a> (Aesop, Fab. 89 P.=140 H.//111 Ch.//91 H-H. <span class=\"greek\">Ἑρμῆς</span> <span class=\"greek\">ὁμοιωθεὶς</span> <span class=\"greek\">ἀνθρώπῳ</span>). <span class=\"greek\">ἀνδρί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:24</a>, 26. <span class=\"greek\">αὐτοῖς</span>, 6:8; 4:2; cf. versículo 6. <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">τοιούτοις</span>, 10:4f. <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοιούτοις</span>, versículos 6f. <span class=\"greek\">ὡμοιώθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῶν</span>, o reino dos céus é semelhante a, pode ser comparado a, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:24</a>; 18:23; 22:2. Também, com referência à parusia futura, <span class=\"greek\">ὁμοιωθήσεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">β</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρ</span>., 25:1. Sobre essas passagens de Mt, nos sentidos de «tornou-se semelhante» ou «será semelhante», ver DCarson, NTS 31, ’85, 277–82. Com <span class=\"greek\">ὡς</span> em vez de dativo (cf. Ezk 32:2): <span class=\"greek\">ὡς</span> <span class=\"greek\">Γόμορρα</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ὡμοιώθημεν</span>, teríamos sido semelhantes a Gomorra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:29</a> (Is 1:9). Dez vezes com o dativo <span class=\"greek\">ὡμοιώθην</span>, GJs 3:2, no lamento de Ana. ② Comparar, com <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>, alguém com outra pessoa ou coisa (<span class=\"greek\">τίῳ</span> <span class=\"greek\">σ</span>’, <span class=\"greek\">ὦ</span> <span class=\"greek\">φίλε</span> <span class=\"greek\">γάμβρε</span>, <span class=\"greek\">καλῶς</span> <span class=\"greek\">εἰκάσδω</span> [= <span class=\"greek\">ὁμοιόω</span>]; «a que, caro noivo, poderia eu adequadamente comparar-te?», Sappho, Fgm. 127 D. 2 [=115 Campbell]; inscrições: AnnBSA 29 p. 35 [IV d.C.]; Did., Gen. 72, 2); com <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, comparar uma coisa com outra (Plut., Cim. et Lucull. 1, 5; SSol 1:9; La 2:13; Wsd 7:9; Is 40:18), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:24</a>, variante de leitura. <span class=\"greek\">τίνι</span> … <span class=\"greek\">ὁμοιώσω</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γενεὰν</span> <span class=\"greek\">ταύτην</span>;, a que compararei esta geração?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:31</a>. <span class=\"greek\">τίνι</span> <span class=\"greek\">ὁμοιώσω</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>;, a que compararei o reino de Deus?, 13:20; cf. versículo 18. Com combinação de duas ideias: <span class=\"greek\">πῶς</span> <span class=\"greek\">ὁμοιώσωμεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>;, como retrataremos o reino de Deus?, e a que compararemos o reino de Deus?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:30</a> (<span class=\"greek\">πῶς</span> aqui equivale a <span class=\"greek\">τίνι</span>: ver HLjungvik, Eranos 62, ’64, 33; para o verbo, cf. Is 40:18 e ver HBartsch, TZ, 15, ’59, 126–28).—DELG s.v. <span class=\"greek\">ὅμοιο</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοίωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοίωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὁμοιόω</span>; Pla., Parm. 132d; 133d, Phdr. 250b; Ps.-Aristot., Int. 1, 16a, 7f; SIG 669, 52; PFay 106, 20; LXX; En 31:2; Just., D. 94, 3). ① Estado de ter experiências em comum, semelhança (<span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τυγχάνειν</span>, «assemelhar-se», Theoph. Ant. 2, 16 [p. 140, 12]): <span class=\"greek\">οὗ</span> (<span class=\"greek\">Χριστοῦ</span>) <span class=\"greek\">καὶ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὁμοίωμα</span> <span class=\"greek\">ἡμᾶς</span> … <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἐγερεῖ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">αὐτοῦ</span>, segundo a semelhança daquele (isto é, assim como Deus o ressuscitou), seu Pai também nos ressuscitará da mesma maneira, ITr 9:2. É provavelmente aqui que cabe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:5</a>: <span class=\"greek\">εἰ</span> <span class=\"greek\">σύμφυτοι</span> <span class=\"greek\">γεγόναμεν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὁμοιώματι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θανάτου</span> <span class=\"greek\">αὐτοῦ</span>, se fomos unidos (isto é, <span class=\"greek\">αὐτῷ</span>, a ele; cf. versículo 4 <span class=\"greek\">συνετάφημεν</span> <span class=\"greek\">αὐτῷ</span>) na semelhança de sua morte (= na mesma morte que ele morreu); mas ver PGächter, ZKT 54, 1930, 88–92; OKuss, D. Römerbr. I, ’63, 301. Sobre a sintaxe, B-D-F § 194, 2; Rob. 528. <span class=\"greek\">ἁμαρτάνειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὁμοιώματι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παραβάσεως</span> <span class=\"greek\">Ἀδάμ</span>, pecar à semelhança da transgressão de Adão (= assim como Adão, que transgrediu um dos mandamentos expressos de Deus), 5:14.—Abstrato pelo concreto, <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁμοιώματα</span> = <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅμοια</span>: <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἃν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁμοιώματα</span> <span class=\"greek\">ποιῇ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθνεσιν</span>, quem fizer coisas semelhantes (às ações) dos gentios = quem agir como os gentios, Hm 4, 1, 9. <span class=\"greek\">περὶ</span> <span class=\"greek\">τοιούτων</span> <span class=\"greek\">τινῶν</span> <span class=\"greek\">ὁμοιωμάτων</span> <span class=\"greek\">πονηρῶν</span>, (pensamentos) sobre outras coisas perversas semelhantes a essas, 4, 1, 1.—<span class=\"greek\">ἐν</span> <span class=\"greek\">τίνι</span> <span class=\"greek\">ὁμοιώματι</span> <span class=\"greek\">παραβάλωμεν</span> <span class=\"greek\">αὐτήν</span>;, com que coisa correspondente poderemos compará-la?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:30</a>, variante de leitura. ② Estado de semelhança na aparência, imagem, forma. ⓐ Imagem, cópia (Dt 4:16ff; 1 Km 6:5; 4 Km 16:10; 1 Macc 3:48; Just., D. 94, 3): <span class=\"greek\">ὁμοίωμα</span> <span class=\"greek\">εἰκόνος</span> <span class=\"greek\">φθαρτοῦ</span> <span class=\"greek\">ἀνθρώπου</span>, imagem de homem corruptível (ver <span class=\"greek\">εἰκών</span> 3; pleonasmo como Maximus Tyr. 27, 3c <span class=\"greek\">εἰς</span> <span class=\"greek\">μορφῆς</span> <span class=\"greek\">εἶδος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:23</a> (cf. Ps 105:20). ⓑ Forma, aparência (escólio sobre Apollon. Rhod. 4, 825–31a <span class=\"greek\">ὁμ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">γυναικός</span> = figura e rosto de uma mulher; Dt 4:12; Josh 22:28; Ezk 1:16; Jos., Ant. 8, 195; Hippol., Ref. 5, 19, 20; 7, 28, 3): <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁμοιώματα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀκρίδων</span> <span class=\"greek\">ὅμοια</span> (variante de leitura <span class=\"greek\">ὅμοιοι</span>) <span class=\"greek\">ἵπποις</span>, os gafanhotos assemelhavam-se a cavalos na aparência, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:7</a>. ③ Não existe consenso geral sobre o significado em duas passagens relacionadas nas quais Paulo emprega esta palavra ao falar da vida terrena de Cristo. As expressões <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμοιώματι</span> <span class=\"greek\">ἀνθρώπων</span> (P 46, Marcion, Orig.: <span class=\"greek\">ἀνθρώπου</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:7</a>, e <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμοιώματι</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἁμαρτίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:3</a>, poderiam significar que o Senhor, em seu ministério terreno, possuía forma inteiramente humana e que seu corpo físico era capaz de pecar, como acontece com os corpos humanos, ou que ele tinha a forma de ser humano e era reconhecido como tal (cf. En 31:2 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>. com genitivo = «semelhante a», «com aparência de»; Aesop, Fab. 140 H., sobre Hermes <span class=\"greek\">ὁμοιωθεὶς</span> <span class=\"greek\">ἀνθρώπῳ</span>), mas sem perder sua identidade como ser divino mesmo neste mundo. À luz do que Paulo diz em geral sobre Jesus, é provável que ele empregue a palavra para destacar tanto que Jesus em sua vida terrena era semelhante aos seres humanos pecadores quanto que não era totalmente semelhante a eles (ver JWeiss, Das Urchristentum1917, 376ff; cf. FGillman, CBQ 49, ’87, 597–604).—Ver a bibliografia em <span class=\"greek\">ἁρπαγμός</span>.—DELG s.v. <span class=\"greek\">ὅμοιο</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοίως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοίως</span>, advérbio de <span class=\"greek\">ὅμοιος</span> (Pind., Hdt. e posteriores), relativo a semelhança em algum aspecto, igualmente, assim, semelhantemente, da mesma maneira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:16</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:11</a>; 10:37; 13:3, 5, variante de leitura (ver <span class=\"greek\">ὡσαύτως</span>) e outros. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">καί</span>, e assim, assim também, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:26</a>; 26:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:33</a>; IPol 5:1. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">μέντοι</span> <span class=\"greek\">καὶ</span>, do mesmo modo, também, Jd 8. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">καί</span> (papiros, EpArist; Jos., Bell. 2, 575, Ant. 14, 216), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:10</a>; 10:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:3f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:25</a>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:27</a>, a leitura varia entre <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τε</span> <span class=\"greek\">καί</span> e <span class=\"greek\">ὁμ</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">καί</span> (variante de leitura). Similarmente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:41</a>, <span class=\"greek\">ὁμοίως</span> <span class=\"greek\">καί</span> (variantes de leitura <span class=\"greek\">ὁμ</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">καί</span> e simplesmente <span class=\"greek\">ὁμ</span>.).—<span class=\"greek\">καθὼς</span> <span class=\"greek\">θέλετε</span> … , <span class=\"greek\">ποιεῖτε</span> <span class=\"greek\">ὁμοίως</span>, como desejais …, fazei do mesmo modo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:31</a>. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">καθώς</span>, da mesma maneira que, 17:28. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">πάλιν</span>, semelhantemente, outra vez, 12:1. Com dativo seguinte: <span class=\"greek\">ὁμ</span>. <span class=\"greek\">πλανᾶσθαι</span> <span class=\"greek\">ἐκείνοις</span>, desviar-se como eles se desviaram, 2:9. Por vezes, a noção de semelhança pode enfraquecer, de modo que <span class=\"greek\">ὁμ</span>. significa também (UPZ 70, 8 [152/151 a.C.] <span class=\"greek\">ὀμνύω</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ψευδῆ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">ὁμοίως</span>; 65, 8f <span class=\"greek\">ὁμ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">Κότταβος</span>, <span class=\"greek\">ὁμ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">Χεντοσνεύς</span>; TestJob 47:6 <span class=\"greek\">ἀφανεῖς</span> <span class=\"greek\">ἐγένοντο</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">σκώληκες</span> … , <span class=\"greek\">ὁμ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">πληγαί</span>; GrBar 9:3; Ath. 9, 2 [para introduzir prova escriturística adicional]): <span class=\"greek\">ταῦτα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ποιεῖ</span>, isto o Filho também faz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:19</a>; cf. 6:11; 21:13.—Como conectivo (Hierocles 26 p. 480 [<span class=\"greek\">ὁμοίως</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καί</span>]; frequente em papiros); mais de um <span class=\"greek\">ὅμ</span>. no sentido «do mesmo modo … também» (edito de Augusto proveniente da Cirenaica, SEG IX, 8, 108; 110 [literatura]= DocsAugTib 311), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:1</a>, 7. Cf. 5:5.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοίωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοίωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὁμοιόω</span>), estado de semelhança, similitude, semelhança (assim desde Pla., Theaet. 176b; Aristot., De Plant. 2, 6, 826b, 32f; Plut., Mor. 53c; Sext. Emp., Hyp. Pyrrh. 75 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὁμοίωσιν</span> <span class=\"greek\">κρίνειν</span>; LXX; TestNapht 2:2; Hippol., Ref. 1, 20, 17 <span class=\"greek\">ὁμ</span>. <span class=\"greek\">θεῷ</span>; Jos., Ant. 13, 67 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὁμοίωσιν</span>; Just., D. 77, 4; Tat.): <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὁμοίωσιν</span> (com <span class=\"greek\">κατ</span>’ <span class=\"greek\">εἰκόνα</span> em Gen 1:26, também em Philo; Iren. 5, 16, 2 [Harv. II 368, 4]; Did., Gen. 59, 5; Theoph. Ant. 2, 18 [p. 144, 7]). A passagem do Gênesis é citada em 1 Cl 33:5; B 5:5; 6:12, e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:9</a> a emprega livremente (cf. Did., Gen. 56, 28). HMerki, <span class=\"greek\">ΟΜΟΙΩΣΙΣ</span> <span class=\"greek\">ΘΕῼ</span> ’52 (de Pla. a Gregório de Nissa).—DELG s.v. <span class=\"greek\">ὅμοιο</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμολογέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμολογέω</span> (<span class=\"greek\">ὁμόλογος</span>, «da mesma opinião»), imperfeito <span class=\"greek\">ὡμολόγουν</span>; futuro <span class=\"greek\">ὁμολογήσω</span>; 1 aoristo <span class=\"greek\">ὡμολόγησα</span>. Passiva: aoristo, 3ª pessoa singular <span class=\"greek\">ὡμολογήθη</span> (Just.); perfeito <span class=\"greek\">ὡμολόγηται</span> (Just.) (Soph., Hdt. e posteriores). ① Comprometer-se a fazer algo por alguém, prometer, assegurar (Hdt., Pla. e outros; IGR IV, 542, 6f [Frígia] <span class=\"greek\">εὐχὴν</span> … , <span class=\"greek\">ἣν</span> <span class=\"greek\">ὡμολόγησεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ῥώμη</span>; Jos., Ant. 6, 40, «consentir»): <span class=\"greek\">ἐπαγγελίας</span> <span class=\"greek\">ἧς</span> (por atração do relativo, em lugar de <span class=\"greek\">ἥν</span>) <span class=\"greek\">ὡμολόγησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἀβραάμ</span>, promessa que Deus fizera a Abraão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:17</a>; <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὅρκου</span> <span class=\"greek\">ὁμ</span>., seguido de infinitivo aoristo (B-D-F § 350; Rob. 1031f), prometer sob juramento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:7</a>. Prometer solenemente, fazer voto: <span class=\"greek\">ὁ</span> … <span class=\"greek\">ὁμολογήσας</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γῆμαι</span> <span class=\"greek\">ἄγαμος</span> <span class=\"greek\">διαμενέτω</span>, Agr 18. ② Compartilhar um ponto de vista ou ter a mesma opinião sobre determinado assunto, concordar (Hdt. 2, 81, sobre semelhança em ritos cultuais; Pla., Sym. 202b <span class=\"greek\">ὁμολογεῖταί</span> <span class=\"greek\">γε</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">εἶναι</span> = há consenso geral de que [o Amor] é um grande deus; provavelmente Cleanthes, na definição de <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθόν</span>: Coll. Alex. p. 229, nº 3, 7; 4 Macc 13:5, chegar juntos a uma conclusão; papiros; Sext. Emp., Adv. Eth. 218, concordância sobre um assunto; Iren. 1, 26, 2 [Harv. I 212, 5] <span class=\"greek\">οἱ</span> … <span class=\"greek\">Ἐβιωναῖοι</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">μὲν</span> <span class=\"greek\">τον</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄντως</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">γεγονέναι</span>; Theoph. Ant. 2, 4 [p. 102, 10]): <span class=\"greek\">ὁμολογοῦσιν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀμφότερα</span>, eles concordam (entre si) sobre todos esses pontos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:8</a> (mas ver 3a abaixo). Esse sentido facilmente passa a ③ Admitir que algo é factual ou verdadeiro, conceder, reconhecer, confessar (Just., D. 80, 1, admissão de algo numa argumentação; semelhantemente 110, 1). ⓐ Em geral, admitir a verdade de algo (Pla., Prot. 317b <span class=\"greek\">ὁμολογῶ</span> <span class=\"greek\">σοφιστὴς</span> <span class=\"greek\">εἶναι</span>; Jos., Ant. 3, 322, admissão da realidade de um fato pelos inimigos; Just., D. 2, 5 <span class=\"greek\">ὡμολόγησα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰδέναι</span>, admissão de ignorância), concordar, admitir: <span class=\"greek\">καθάπερ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ὡμολόγησας</span>, Dg 2:1. <span class=\"greek\">ὁμολογήσαντες</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ξένοι</span> <span class=\"greek\">εἰσίν</span>, reconhecendo que eram (apenas) estrangeiros, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:13</a>. <span class=\"greek\">ὁμολογοῦμεν</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰληφέναι</span>, reconhecemos não ter recebido graça, IMg 8:1. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:8</a>, ver 2 acima. ⓑ Com conotação judicial, prestar uma confissão, confessar, em emprego absoluto: MPol 6:1; 9:2. Com <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>: <span class=\"greek\">ὁμολογῶ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τοῦτό</span> <span class=\"greek\">σοι</span>, <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:14</a>. Seguido de acusativo e infinitivo: <span class=\"greek\">ὡμολόγησεν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">Χριστιανὸν</span> <span class=\"greek\">εἶναι</span>, confessou ser cristão, MPol 12:1 (cf. com infinitivo seguinte: Just., A II, 13, 2 <span class=\"greek\">Χριστιανὸς</span> <span class=\"greek\">εὑρεθῆναι</span> … <span class=\"greek\">ὁμολογῶ</span>; Theoph. Ant. 2, 8 [p. 118, 7] <span class=\"greek\">ὁμ</span>. <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πλάνα</span> <span class=\"greek\">πνεύματα</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">δαίμονες</span>). Cf. a ação de João Batista ao responder ao interrogatório das autoridades: <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡμολόγησεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἠρνήσατο</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡμολόγησεν</span> <span class=\"greek\">ὅτι</span> (segue-se discurso direto), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:20</a> (cf. Plut., Mor. 509e, em interrogatório; contraste entre <span class=\"greek\">ὁμ</span>. e <span class=\"greek\">ἀρνεῖσθαι</span>, como em Thu. 6, 60, 3; Phalaris, Ep. 147, 3 <span class=\"greek\">ὁμολογοῦμεν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀρνησόμεθα</span>; Aelian, NA 2, 43; Jos., Ant. 6, 151; cf. MPol 9:2 e muitas passagens adiante). ⓒ Com ênfase na admissão de uma falta (X., An. 1, 6, 7; Ps.-Aristot., Mirabilia 152 <span class=\"greek\">ὁμολογοῦντες</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἐπιώρκησαν</span>; Arrian, Anab. 7, 29, 2 [ver <span class=\"greek\">ἴασις</span> 2]; Jos., Ant. 6, 151): <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ὁμολογῶμεν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">ἡμῶν</span>, se confessarmos nossos pecados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:9</a> (cf. Appian, Liby. 79 §369 <span class=\"greek\">ὁμολογοῦντες</span> <span class=\"greek\">ἁμαρτεῖν</span>; Sir 4:26; ApcSed 13:3 [uso absoluto]; <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἁμάρτημα</span>, Did., Gen. 93, 6; inscrição de Sardes: <span class=\"greek\">ὁμολογῶ</span> <span class=\"greek\">τ</span>[<span class=\"greek\">ὸ</span>| <span class=\"greek\">ἁμάρτημ</span>]<span class=\"greek\">α</span> <span class=\"greek\">Μηνί</span> = confesso meu pecado a Men; ver FSteinleitner, Die Beicht 1913, p. 46 nº 20, 4f= ILydiaKP p. 15, nº 25). Ver <span class=\"greek\">ἐξομολογέω</span> 2a. ④ Reconhecer algo, geralmente em público, declarar, professar, afirmar, louvar. ⓐ Declaração pública enquanto tal (Herodian. 4, 4, 5 [de Steinleitner, p. 109, ver 3c], expressão de agradecimento): <span class=\"greek\">ὁμολογήσω</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὅτι</span> (seguido de discurso direto), eu lhes declararei abertamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:23</a>. Com infinitivo seguinte (X., Mem. 2, 3, 9; Jos., Ant. 9, 254): <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὁμολογοῦσιν</span> <span class=\"greek\">εἰδέναι</span>, afirmam conhecer a Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:16</a> (em oposição a <span class=\"greek\">ἀρνεῖσθαι</span>, ver 3b). ⓑ Profissão de lealdade (<span class=\"greek\">ὁμολογῶ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">χριστιανός</span>, Theoph. Ant. 1, 1 [p. 58, 11]).—Especialmente sobre confessar Cristo, ou o ensino de sua comunidade/igreja; com duplo acusativo (B-D-F § 157, 2; 416, 3; Rob. 480.—Jos., Ant. 5, 52; Just., A II, 5, 1 <span class=\"greek\">εἰ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὡμολογοῦμεν</span> <span class=\"greek\">βοηθόν</span>, D. 35, 2 <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">ὁμολογεῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χριστόν</span>): <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ὁμολογήσῃς</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">Ἰησοῦν</span>, se confessares Jesus como Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:9</a> (cf. <span class=\"greek\">τὸν</span> <span class=\"greek\">Δία</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">θεόν</span>, Orig., C. Cels. 5, 46, 7). <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">Χριστόν</span>, confessar que ele é o Messias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:22</a>. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">σαρκοφόρον</span>, ISm 5:2. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ἐληλυθότα</span>, reconhecer que Jesus Cristo veio em carne, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:2</a>; cf. 2J 7. Com acusativo e infinitivo (Isocr., Or. 4, 100, 61d; Aelian, VH 1, 27; Orig., C. Cels. 1, 41, 9): <span class=\"greek\">ὁμ</span>. <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ἐληλυθέναι</span>, Pol 7:1a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:2</a>, variante de leitura. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐχαριστίαν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σωτῆρος</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>., ISm 7:1. Seguido de <span class=\"greek\">ὅτι</span> (Isocr., Or. 11, 5, 222d, porém no sentido 2; Just., D. 39, 6): <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ὅτι</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:15</a>. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ὅτι</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">ἔχετε</span>, Hs 9, 28, 7 (oposto a <span class=\"greek\">ἀρν</span>.). Com um só acusativo da pessoa confessada, ou da pessoa que se declara possuir uma qualidade explicitada pelo contexto (Just., D. 35, 1, 2 <span class=\"greek\">Ἰησοῦν</span> … <span class=\"greek\">ὁμολογεῖν</span>; Did., Gen. 176, 13 <span class=\"greek\">ὁ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὁμολογῶν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ποιεῖ</span>; Theoph. Ant. 3, 9 [p. 222, 13] <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὁμ</span>.): <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:23</a> (em oposição a <span class=\"greek\">ἀρν</span>., como Mel., P. 73, 537 <span class=\"greek\">ἀπαρνήσω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὁμολογήσαντά</span> <span class=\"greek\">σε</span>). <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span>, 4:3 (ver <span class=\"greek\">λύω</span> 4, final). Cf. 2 Cl 3:2a. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, reconhecer alguém por meio de alguma coisa: <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔργοις</span>, 4:3; cf. 3:4. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ὁμολογήσωμεν</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐσώθημεν</span>, se confessarmos aquele por quem fomos salvos, 3:3. O acusativo (<span class=\"greek\">αὐτόν</span>) é suprido pelo contexto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:42</a>; cf. Hs 9, 28, 4.—Com acusativo de coisa: <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>, Pol 7:1b. <span class=\"greek\">ὁμ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">καλὴν</span> <span class=\"greek\">ὁμολογίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:12</a> (<span class=\"greek\">ὁμ</span>. <span class=\"greek\">ὁμολογίαν</span> = «fazer uma promessa», Pla., Crito 52a; Jer 51:25; mas = «dar testemunho de uma convicção», Philo, Mut. Nom. 57, Abr. 203).—Em lugar de acusativo da pessoa, pode ocorrer <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, confessar alguém, aramaísmo (ver Mlt-H. 463f; B-D-F § 220, 2; EbNestle, ZNW 7,1906, 279f; 8, 1907, 241; 9, 1908, 253; FBurkitt, Earliest Sources for the Life of Jesus 1910, 19f). <span class=\"greek\">ὅστις</span> <span class=\"greek\">ὁμολογήσει</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>, todo aquele que me confessar diante das pessoas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:32a</a>; semelhantemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:8a</a>. Mas 2 Cl 3:2 usa o acusativo ao citar essa palavra (ver acima.—Nas três últimas passagens, o oposto é <span class=\"greek\">ἀρν</span>.). O reconhecimento do crente por Jesus no dia do juízo complementa essa confissão: <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:32b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:8b</a>. <span class=\"greek\">αὐτόν</span>, 2 Cl 3:2b (oposto a <span class=\"greek\">ἀρν</span>. em todas essas passagens.—GBornkamm, D. Wort Jesu vom Bekennen [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:32</a>]: Pastoraltheologie 34, ’39, 108–18). <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:5</a>.—Emprego absoluto na passiva: <span class=\"greek\">στόματι</span> <span class=\"greek\">ὁμολογεῖται</span>, com a boca se faz confissão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:10</a>. ⓒ Louvar, com dativo (Dio Chrys. 10 [11], 147; B-D-F § 187, 4; Rob. 541. Na LXX, <span class=\"greek\">ἐξομολογεῖσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>. Ver <span class=\"greek\">ἐξομολογέω</span> 4): <span class=\"greek\">καρπὸς</span> <span class=\"greek\">χειλέων</span> <span class=\"greek\">ὁμολογούντων</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">αὐτοῦ</span>, fruto de lábios que louvam seu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:15</a>.—B. 1267. DELG s.v. <span class=\"greek\">ὁμό</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμολόγησις, ήσεως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμολόγησις</span>, <span class=\"greek\">ήσεως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὁμολογέω</span>; Diod S 17, 68, 4), ato de professar lealdade, confessar (em oposição a <span class=\"greek\">ἄρνησις</span>), Hs 9, 28, 7.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμολογία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμολογία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὁμολογέω</span>; Hdt., Thu. e outros; inscrições, papiros, LXX, Philo; Jos., Bell. 4, 92, Ant. 15, 52, C. Ap. 1, 89 e outros; Just., Did., Hippol.; empréstimo na literatura rabínica). ① Expressão de lealdade como ação, profissão, confissão (ver <span class=\"greek\">ὁμολογέω</span> 4b; <span class=\"greek\">θανάτου</span> <span class=\"greek\">καταφρονεῖν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁμολογίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστιανισμοῦ</span> = desprezar a morte em favor de confessar lealdade a Cristo, Orig., C. Cels. 2, 15, 16), em sentido ativo: <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑποταγὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>, a submissão de vossa profissão do evangelho (= vossa profissão do evangelho se expressa na obediência submissa às exigências dele), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:13</a>. ② Declaração de lealdade como conteúdo de um ato, confissão, reconhecimento feito por alguém: Jesus como <span class=\"greek\">ἀρχιερεὺς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ἡμῶν</span>, sumo sacerdote (de quem fala) nossa confissão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:1</a>. <span class=\"greek\">κρατεῖν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁμ</span>., manter firme a confissão, 4:14. <span class=\"greek\">κατέχειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁμ</span>, <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλπίδος</span> <span class=\"greek\">ἀκλινῆ</span>, manter sem vacilar a confissão da esperança, 10:23. <span class=\"greek\">ὁμολογεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καλὴν</span> <span class=\"greek\">ὁμ</span>., fazer a boa profissão de fé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:12</a> (<span class=\"greek\">ὁμολογέω</span> 4b). Jesus, o primeiro mártir cristão (ver <span class=\"greek\">μαρτυρέω</span> 1c), deu testemunho da mesma boa profissão de fé, versículo 13 (ver CTurner, JTS 28, 1927, 270–3).—ASeeberg, Der Katechismus der Urchristenheit 1903, 143; 172; 186; PFeine, D. Gestalt d. apostolischen Glaubensbekenntnisses in d. Zeit des NTs 1925; EvDobschütz, D. Apostolicum in bibl.-theol. Beleuchtung ’32; GBornkamm, <span class=\"greek\">Ὁμολογία</span>: Her 71, ’36, 377–93, também ThBl 21, ’42, 56–66 (Hb); AHunter, Paul and His Predecessors ’40; PCarrington, The Primitive Christian Catechism ’40; OCullmann, Les premières confessions de foi chrétiennes ’43; VNeufeld, The Earliest Christian Confessions ’63; HvCampenhausen, Das Bekenntnis im Urchristentum, ZNW 63, ’72, 210–53.—DELG s.v. <span class=\"greek\">ὁμό</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμολογουμένως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμολογουμένως</span> (<span class=\"greek\">ὁμολογέω</span>), advérbio (Thu. e outros; papiros, 4 Macc), relativo àquilo em que há concordância geral, incontestavelmente, inegavelmente, certamente, sem dúvida (Thu. 6, 90, 3; X., An. 2, 6, 1; Pla., Menex. 243c; Diod S 9, 11, 2; 13, 27, 4; Epict. 1, 4, 7; Vett. Val. 168, 17; UPZ 161, 65 [119 a.C.]; 162 V, 32; 4 Macc 6:31; 7:16; 16:1; EpArist 24 [ver p. xxix Wendl.]; Jos., Ant. 1, 180; 2, 229.—Crönert 241; Hippol., Ref. 5, 7, 22; 9, 10, 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:16</a>; Dg 5:4.—M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμονοέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμονοέω</span> (Thu. e outros; Dio Chrys. 4, 42; 11 [12], 74; Epict. 2, 20, 31; 2, 22, 24; inscrições; Sb 4827, 5; LXX; EpArist 185; Jos., Ant. 12, 283, C. Ap. 2, 294), ter a mesma opinião, estar de acordo, viver em harmonia: <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> <span class=\"greek\">κτλ</span>., 1 Cl 62:2.—Renehan ’75, 150. DELG s.v. <span class=\"greek\">ὁμό</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμόνοια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμόνοια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὁμονέω</span>; Thu. e outros; Diod S 12, 75, 3; Epict. 4, 5, 35; Plut., Ages. 5, 5; Dio Chrys. 21 [38] <span class=\"greek\">περὶ</span> <span class=\"greek\">ὁμονοίας</span> e outros; Ael. Aristid. 23 e 24 K.=42 e 44 D.: <span class=\"greek\">περὶ</span> <span class=\"greek\">ὁμονοίας</span>; inscrições, por exemplo IPriene 54, 40, sobre partes reconciliadas; papiros tardios; LXX; Ps.-Phoc. 74; 219: outras referências em Horst p. 164 e 253; Philo; Jos., Bell. 2, 345, Ant. 13, 67, C. Ap. 2, 179; TestJos 17:3; SibOr 3, 375; empréstimo na literatura rabínica), estado de concordância de opiniões, unidade de pensamento, unanimidade, concórdia, harmonia. Com <span class=\"greek\">ἀγάπη</span>, IEph 4:1. Com <span class=\"greek\">εἰρήνη</span> (ver esse verbete, 1b), 1 Cl 60:4; 63:2; 65:1; com outros conceitos semelhantes, 61:1. Com <span class=\"greek\">πίστις</span> e <span class=\"greek\">ἀγάπη</span>, IPhld 11:2; com outras virtudes cristãs, Hm 8:9; <span class=\"greek\">ἐνδύσασθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁμ</span>., revestir-se de harmonia, isto é, estar de acordo, 1 Cl 30:3. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, vossa unanimidade na fé, IEph 13:1; <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>., harmoniosamente, em concordância (Ps 54:15; 82:6; Wsd 18:9), 1 Cl 9:4; 11:2; 20:3; 34:7 (<span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span>, como em Ps 82:6); também <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὁμονοία</span>, 21:1. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰρήνῃ</span>, 20:10; cf. versículo 11. <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>., o amor tudo faz em harmonia, 49:5. Daí <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ἀγάπης</span>, fazer algo em harmonia amorosa, 50:5. <span class=\"greek\">διαμένετε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ὑμῶν</span>, continuai em vossa unanimidade (presente), ITr 12:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">θεοῦ</span>, em harmonia divina (isto é, harmonia produzida por Deus), IMg 6:1; 15; IPhld, inscrição; <span class=\"greek\">σύμφωνοι</span> <span class=\"greek\">ὄντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁμ</span>., estando em concórdia harmoniosa, IEph 4:2 (cf. Philo, Mut. Nom. 200 <span class=\"greek\">τὸ</span> <span class=\"greek\">σύμφωνον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁμονοίας</span>).—Personificada como virtude, Hs 9, 15, 2 (cf. a divindade <span class=\"greek\">Ὁμόνοια</span>: Apollon. Rhod. 2, 718; Nicol. Dam.: 90 Fgm. 130, 69 Jac.; Paus. 5, 14, 9; Chariton 3, 2, 16; CIG 4342, 3; OGI 479, 4; 11; 536, 6; SIG índice III p. 179b).—HKramer, Quid valeat <span class=\"greek\">ὁμόνοια</span> in litteris Graecis, tese, Gött. 1915; JdeRomilly, Vocabulaire et propaganda ou les premiers emplois du mot <span class=\"greek\">ὁμόνοια</span>: Mélanges … offerts à PChantraine ’72, 199–209, AErskine, The Hellenistic Stoa ’90, 90–95.—DELG s.v. <span class=\"greek\">ὁμό</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμόσε</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμόσε</span> (<span class=\"greek\">ὁμός</span>, «um e o mesmo, comum»), advérbio (Hom. e outros; papiros), para um mesmo lugar, também em lugar de <span class=\"greek\">ὁμοῦ</span> = juntos (Polyb. 6, 7, 5 e outros; Vett. Val. índice; PGiss 4, 6 [II d.C.]; Jos., Ant. 12, 292.—B-D-F § 103; Rob. 299f): <span class=\"greek\">ὁμόσε</span> <span class=\"greek\">ὄντων</span> <span class=\"greek\">αὐτῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:18</a>, variante de leitura.—DELG s.v. <span class=\"greek\">ὁμό</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμότεχνος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμότεχνος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὁμός</span>, «um e o mesmo», <span class=\"greek\">τέχνη</span>; desde Hdt. 2, 89; Appian, Bell. Civ. 4, 27 §119; Lucian; Alciphron 3, 25, 4; Philostrat., Vi. Soph. 1, 9 p. 11, 27; Ps.-Phocyl. 88; Jos., Ant. 8, 334; IKosPH 324; PFouad 37, 7 [48 d.C.]), que pratica o mesmo ofício, da mesma profissão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:3</a>.—DELG s.v. <span class=\"greek\">ὁμό</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοῦ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοῦ</span>, advérbio (Hom. e posteriores; empréstimo na literatura rabínica). ① Relativo a estar junto no mesmo lugar, juntos: <span class=\"greek\">ἦσαν</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">Σίμων</span> <span class=\"greek\">Πέτρος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Θωμᾶς</span> …, Simão Pedro, Tomé … estavam juntos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:2</a>. <span class=\"greek\">ἦσαν</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span>, estavam todos juntos num mesmo lugar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:1</a> (<span class=\"greek\">πάντες</span> <span class=\"greek\">ὁμ</span>., como em Jos., Ant. 7, 276). <span class=\"greek\">ἐστάθησαν</span> <span class=\"greek\">ὅμ</span>., tinham ficado juntos, Hs 9, 4, 1. <span class=\"greek\">συναχθέντες</span> <span class=\"greek\">ὁμοῦ</span>, reunidos em grupo, GJs 9:1. ② Relativo à simultaneidade, juntos ao mesmo tempo, em companhia: <span class=\"greek\">ἔτρεχον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ὁμ</span>., os dois corriam juntos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:4</a> (cf. TestNapht 5:3). <span class=\"greek\">τὰ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ὁμ</span>., essas duas coisas ao mesmo tempo, IMg 5:1. <span class=\"greek\">πάντες</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">εὐφρανθήσονται</span>, todos se alegrarão juntos, Hv 3, 4, 2; cf. GPt 8:32 (cf. En 6:5; Jos., Ant. 7, 276 <span class=\"greek\">ὁμοῦ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">γνώμῃ</span>). <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σπείρων</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">χαίρῃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θερίζων</span>, para que o semeador e o ceifeiro se alegrem juntos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:36</a> (o duplo particípio como em Jos., Bell. 6, 271). <span class=\"greek\">πάντα</span> <span class=\"greek\">ὁμ</span>. <span class=\"greek\">καλά</span> <span class=\"greek\">ἐστιν</span>, todas as coisas juntas são boas, IPhld 9:2. <span class=\"greek\">ἐβάσταζον</span> <span class=\"greek\">ὁμ</span>., carregavam juntos, Hs 9, 3, 5.—DELG s.v. <span class=\"greek\">ὁμό</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμόφρων, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμόφρων</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὁμός</span>, «comum», <span class=\"greek\">φρήν</span>; Hom. e posteriores; Plut., Mor. 432c; OGI 515, 4; Kaibel, advérbio «em simpatia», 493, 5f; Ps.-Phocyl. 30, ver <span class=\"greek\">ὁμόνοια</span>), relativo a compartilhar a mesma disposição, unido em espírito, harmonioso (com <span class=\"greek\">συμπαθής</span> e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:8</a> (Strabo 6, 3, 3 <span class=\"greek\">ὁμόφρονας</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἀλλήλων</span> <span class=\"greek\">ἀδελφούς</span>).—DELG s.v. <span class=\"greek\">φρήν</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμόφυλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμόφυλος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὁμός</span>, «comum», <span class=\"greek\">φῦλον</span>, «tribo»; cf. <span class=\"greek\">φυλή</span>; Eur., Pla., X. e outros; papiros; Jos., Ant. 17, 313), relativo a pertencer à mesma tribo, membro da mesma tribo, compatriota; substantivado <span class=\"greek\">ὁ</span> <span class=\"greek\">ὁμ</span>. (Eth. Epic. coluna 20, 19; Alciphron 1, 10, 5; 2 Macc 4:10; 3 Macc 3:21; Philo; Jos., Ant. 17, 285; Just., A I, 14, 3), 1 Cl 4:10.—DELG s.v. <span class=\"greek\">φῦλον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁμοφωνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁμοφωνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὁμός</span>, «comum», <span class=\"greek\">φωνή</span>; Aristot., Pol. 2, 5; Philo, Conf. Lingu. 6). Do sentido básico «estado de harmonia na expressão» (ver L-S-J-M s.v.) deriva a extensão figurada: estado de concordância com outros, harmonia (Ecphantus em Stob. 4, 7, 64), 1 Cl 51:2.—DELG s.v. <span class=\"greek\">φωνή</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0255-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄμφαξ, ακος</h1><div class=\"entry-meta\"><span>substantivo feminino/masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄμφαξ</span>, <span class=\"greek\">ακος</span> (Hom. e outros; inscrições, LXX), feminino <span class=\"greek\">ἡ</span> e, posteriormente, também masculino <span class=\"greek\">ὁ</span> (por exemplo, Plut., Mor. 138e; 648f; Jer 38:30; Ezk 18:4, variante de leitura), uva verde, uva ainda não madura (proveniente de citação de origem desconhecida), 1 Cl 23:4 = 2 Cl 11:3.—DELG.</p></section></article>"};
